<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import api from '../../services/api.js'
import { toast } from '../../services/toast.js'

const props = defineProps({ room: { type: Object, required: true }, participants: { type: Array, default: () => [] }, isHost: Boolean })
const emit = defineEmits(['move'])
const router = useRouter()
const rooms = ref([]), meta = ref({}), help = ref([]), count = ref(2), duration = ref(15), noticeText = ref(''), assignments = ref({}), busy = ref(false), loading = ref(false), now = ref(Date.now())
const parentId = computed(() => props.room.parentRoomId || props.room.id)
const assignableParticipants = computed(() => props.participants.filter((person) =>
  !person.isLocal && (person.id.startsWith('guest-') || person.id.startsWith('host-'))))
const canReturnDirect = computed(() => props.participants.some((person) => person.isLocal && person.id.startsWith('host-')) || Boolean(credentials(parentId.value).guestSecret))
const remaining = computed(() => meta.value.deadlineAt ? Math.max(0, Math.ceil((meta.value.deadlineAt - now.value) / 1000)) : null)
let disposed = false, timer = null, clock = null, lastNoticeAt = 0
function credentials(id = parentId.value) { try { return JSON.parse(sessionStorage.getItem(`meetspace:approval:${id}`) || '{}') || {} } catch { return {} } }
async function refresh() {
  clearTimeout(timer); loading.value = true
  try {
    const sourceId = props.room.parentRoomId ? props.room.id : parentId.value
    const c = credentials(sourceId)
    const endpoint = `/rooms/${sourceId}/breakouts${props.room.parentRoomId ? '/context' : props.isHost ? '?include=participants' : ''}`
    const response = await api.get(endpoint, { headers: { 'x-meetspace-request-id': c.requestId, 'x-meetspace-guest-secret': c.guestSecret } })
    if (disposed) return
    rooms.value = props.room.parentRoomId ? [] : response.data.data; meta.value = props.room.parentRoomId ? response.data.data : response.data.meta || {}
    if (!props.room.parentRoomId && rooms.value.length && count.value > 6 - rooms.value.length) count.value = Math.max(1, 6 - rooms.value.length)
    if (props.room.parentRoomId && meta.value.notice?.at && meta.value.notice.at !== lastNoticeAt) {
      lastNoticeAt = meta.value.notice.at; toast.info(`Pesan fasilitator: ${meta.value.notice.text}`)
    }
    if (props.isHost && !props.room.parentRoomId) {
      const result = await api.get(`/rooms/${parentId.value}/breakouts/help`)
      if (!disposed) help.value = result.data.data
    }
  } catch (error) { if (!disposed) toast.error(error) }
  finally { loading.value = false; if (!disposed) timer = setTimeout(refresh, 5000) }
}
async function create() { if (busy.value) return; busy.value = true; try { await api.post(`/rooms/${parentId.value}/breakouts`, { count: count.value }); await refresh(); toast.success('Breakout rooms siap dimasuki peserta.') } catch (error) { toast.error(error) } finally { busy.value = false } }
async function join(room) { if (busy.value || !room) return; busy.value = true; try { const result = await api.post(`/rooms/${parentId.value}/breakouts/${room.id}/join`, credentials()); emit('move', result.data.data) } catch (error) { toast.error(error) } finally { busy.value = false } }
async function assign(identity) { const roomId = assignments.value[identity]; if (busy.value || !roomId) return; busy.value = true; try { await api.post(`/rooms/${parentId.value}/breakouts/${roomId}/assign`, { identity }); meta.value = { ...meta.value, assignments: { ...(meta.value.assignments || {}), [identity]: roomId } }; toast.success('Tugas tersimpan. Peserta akan menerima tombol masuk kelompok.') } catch (error) { toast.error(error) } finally { busy.value = false } }
function assignedRoomName(identity) { return rooms.value.find((room) => room.id === meta.value.assignments?.[identity])?.name }
async function setTimer(minutes) { busy.value = true; try { const response = await api.patch(`/rooms/${parentId.value}/breakouts/timer`, { minutes }); meta.value = { ...meta.value, deadlineAt: response.data.data.deadlineAt }; toast.success(minutes ? 'Timer kelompok dimulai.' : 'Timer kelompok dihentikan.') } catch (error) { toast.error(error) } finally { busy.value = false } }
async function broadcast() { if (!noticeText.value.trim()) return; busy.value = true; try { await api.post(`/rooms/${parentId.value}/breakouts/notice`, { text: noticeText.value }); noticeText.value = ''; toast.success('Pengumuman tersimpan untuk semua kelompok.') } catch (error) { toast.error(error) } finally { busy.value = false } }
async function askHelp() { busy.value = true; try { await api.post(`/rooms/${props.room.id}/breakouts/help`, credentials(props.room.id)); toast.success('Fasilitator diberi tahu kamu butuh bantuan.') } catch (error) { toast.error(error) } finally { busy.value = false } }
onMounted(() => { refresh(); clock = setInterval(() => { now.value = Date.now() }, 1000) })
onUnmounted(() => { disposed = true; clearTimeout(timer); clearInterval(clock) })
</script>
<template>
  <section class="breakout-panel">
    <div class="breakout-summary"><span>{{room.parentRoomId?'SEDANG DI KELOMPOK':`${rooms.length} RUANG KELOMPOK`}}</span><span v-if="remaining !== null" class="countdown">◷ {{String(Math.floor(remaining/60)).padStart(2,'0')}}:{{String(remaining%60).padStart(2,'0')}}</span><button class="refresh-link" :disabled="loading" @click="refresh">{{loading?'Memuat…':'Perbarui ↻'}}</button></div>
    <template v-if="room.parentRoomId">
      <div class="child-room"><h3>{{room.name}}</h3><p>Kamera, audio, dan chat di kelompok ini terpisah dari room utama.</p><div v-if="meta.assignedRoomId && meta.assignedRoomId !== room.id" class="assignment"><strong>Kamu ditugaskan ke {{meta.assignedRoomName || 'kelompok lain'}}.</strong><button :disabled="busy" @click="join({id:meta.assignedRoomId})">Masuk kelompok ↗</button></div><div class="current-roster"><strong>Di kelompok ini · {{participants.length}} hadir</strong><div v-for="person in participants" :key="person.id" class="roster-person"><span class="roster-avatar">{{person.name.charAt(0).toUpperCase()}}</span><span>{{person.name}}{{person.isLocal?' (Kamu)':''}}</span></div></div><p v-if="meta.notice" class="notice">Pesan fasilitator: {{meta.notice.text}}</p><div class="controls"><button :disabled="busy" @click="askHelp">✋ Minta bantuan fasilitator</button><button @click="canReturnDirect ? emit('move',{roomId:room.parentRoomId}) : router.push({name:'lobby',params:{roomId:room.parentRoomId}})">← Kembali ke room utama</button></div></div>
    </template>
    <template v-else>
      <div v-if="meta.assignedRoomId" class="assignment"><strong>Kamu ditugaskan ke {{rooms.find(r=>r.id===meta.assignedRoomId)?.name || 'kelompok'}}.</strong><button :disabled="busy || !rooms.some(r=>r.id===meta.assignedRoomId)" @click="join(rooms.find(r=>r.id===meta.assignedRoomId))">Masuk kelompok ↗</button></div>
      <div class="breakout-workspace">
        <section class="room-map" aria-label="Daftar ruang kelompok"><div class="section-heading"><div><small>ROOM MAP</small><h3>Kelompok yang tersedia</h3></div><span>{{rooms.length}} / 6</span></div>
          <p v-if="!rooms.length" class="empty-room">{{loading?'Memuat ruang kelompok…':'Belum ada ruang kelompok. Fasilitator dapat membuatnya di sebelah kanan.'}}</p>
          <div class="room-grid"><article v-for="child in rooms" :key="child.id" class="room-card"><header><div><small>▦ RUANG KELOMPOK</small><h4>{{child.name}}</h4></div><span v-if="isHost" class="occupancy-count">{{child.presenceAvailable===false?'—':child.participants?.length ?? 0}} hadir</span></header>
            <div v-if="isHost" class="room-roster"><p v-if="child.presenceAvailable===false">Daftar peserta belum tersedia. Coba perbarui.</p><p v-else-if="!child.participants?.length">Belum ada yang masuk.</p><div v-for="person in child.participants || []" :key="person.identity" class="roster-person"><span class="roster-avatar">{{person.name.charAt(0).toUpperCase()}}</span><strong>{{person.name}}</strong><small v-if="person.identity.startsWith('host-')">Host</small></div></div>
            <p v-else class="room-card-description">Masuk untuk berdiskusi bersama kelompok.</p><button :disabled="busy" @click="join(child)">Masuk ruang ↗</button>
          </article></div>
        </section>
        <aside v-if="isHost" class="facilitator-desk"><div class="section-heading"><div><small>FACILITATOR DESK</small><h3>Atur kelompok</h3></div></div>
          <form v-if="rooms.length<6" class="create-form" @submit.prevent="create"><label>Tambah ruang<input v-model.number="count" type="number" min="1" :max="6-rooms.length" required /></label><button :disabled="busy">Buat ruang</button></form>
          <section v-if="rooms.length" class="desk-section"><h4>Tugaskan peserta</h4><p>Peserta menerima undangan Masuk atau Batal.</p><div v-for="person in assignableParticipants" :key="person.id" class="assign-row"><div class="assign-person"><strong>{{person.name}}</strong><small v-if="assignedRoomName(person.id)">Ditugaskan: {{assignedRoomName(person.id)}}</small></div><select v-model="assignments[person.id]" :aria-label="`Kelompok untuk ${person.name}`"><option value="">Pilih kelompok</option><option v-for="child in rooms" :key="child.id" :value="child.id">{{child.name}}</option></select><button :disabled="busy || !assignments[person.id]" @click="assign(person.id)">Tugaskan</button></div><p v-if="!assignableParticipants.length">Belum ada peserta lain di room utama.</p></section>
          <section v-if="rooms.length" class="desk-section"><h4>Timer kelompok</h4><label>Durasi (menit)<input v-model.number="duration" type="number" min="1" max="120" /></label><div class="controls"><button :disabled="busy" @click="setTimer(duration)">Mulai timer</button><button :disabled="busy" @click="setTimer(0)">Hentikan</button></div></section>
          <section v-if="rooms.length" class="desk-section"><h4>Pengumuman</h4><label>Pesan untuk semua kelompok<textarea v-model="noticeText" maxlength="240" rows="2" /></label><button :disabled="busy || !noticeText.trim()" @click="broadcast">Kirim pesan</button></section>
          <section v-if="rooms.length" class="desk-section"><h4>Permintaan bantuan</h4><p v-if="!help.length">Belum ada permintaan.</p><div v-for="item in help" :key="item.id" class="help-row"><span>{{item.participantName}} · {{item.roomName}}</span><button :disabled="busy" @click="join(rooms.find(r=>r.id===item.roomId))">Kunjungi ↗</button></div></section>
        </aside>
      </div>
    </template>
  </section>
</template>
<style scoped>
.breakout-panel{padding:18px 22px 28px;display:grid;gap:16px;color:var(--text-primary)}.breakout-panel p{font-size:12px;color:var(--text-secondary);line-height:1.5;margin:0}.breakout-panel h3,.breakout-panel h4{margin:0}.breakout-summary{display:flex;align-items:center;gap:12px;font-size:11px;font-weight:1000;letter-spacing:.08em;color:var(--text-secondary)}.breakout-summary .countdown{padding:5px 10px;border:2px solid var(--border-color);border-radius:8px;color:var(--text-primary);background:var(--bg-elevated)}.refresh-link{margin-left:auto;background:none!important;border:0!important;text-decoration:underline;color:var(--text-primary)!important;box-shadow:none!important}.breakout-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(275px,330px);gap:18px;align-items:start}.section-heading{display:flex;justify-content:space-between;align-items:end;gap:12px;padding-bottom:10px;border-bottom:2px dashed var(--border-color)}.section-heading small,.room-card header small{font-size:10px;letter-spacing:.12em;font-weight:1000;color:var(--text-secondary)}.section-heading h3{font-family:var(--font-display);font-size:21px;margin:3px 0 0}.section-heading>span{font-size:11px;font-weight:1000}.room-map,.facilitator-desk{display:grid;gap:13px;min-width:0}.room-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.room-card{display:flex;flex-direction:column;gap:11px;min-width:0;min-height:170px;padding:14px;border:2px solid var(--border-color);border-radius:13px;background:var(--bg-elevated);box-shadow:3px 4px 0 var(--border-color)}.room-card header{display:flex;justify-content:space-between;gap:8px;align-items:start}.room-card h4{font-family:var(--font-display);font-size:16px;margin-top:4px;overflow-wrap:anywhere}.occupancy-count{flex:none;border:1px solid var(--border-color);border-radius:999px;padding:4px 7px;background:var(--bg-surface);font-size:10px;font-weight:900}.room-roster{display:grid;gap:6px;flex:1;align-content:start}.roster-person{display:flex;align-items:center;gap:7px;min-width:0;font-size:11px}.roster-person strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.roster-person small{margin-left:auto;color:var(--text-secondary)}.roster-avatar{display:grid;place-items:center;width:24px;height:24px;flex:none;border:1px solid var(--border-color);border-radius:7px;background:var(--bg-surface);font-weight:1000}.room-card>button{align-self:start;margin-top:auto}.room-card-description{flex:1}.facilitator-desk{padding:15px;border:2px solid var(--border-color);border-radius:13px;background:var(--bg-elevated)}.desk-section{display:grid;gap:8px;padding-top:11px;border-top:1px dashed var(--border-color)}.desk-section h4{font-family:var(--font-display);font-size:16px}.assign-row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px;padding:7px 0;border-bottom:1px dashed var(--border-color)}.assign-person{grid-column:1/-1;display:flex;justify-content:space-between;gap:8px;min-width:0;font-size:12px}.assign-person small{color:var(--text-secondary);font-size:10px;text-align:right}.create-form{display:flex;align-items:end;gap:8px}.create-form label{max-width:115px}.breakout-panel label{display:grid;gap:5px;font-size:11px;font-weight:900}.breakout-panel input,.breakout-panel select,.breakout-panel textarea{min-width:0;width:100%;padding:8px;border:2px solid var(--border-color);border-radius:8px;background:var(--bg-surface);color:var(--text-primary)}.breakout-panel button{padding:8px 10px;border:2px solid var(--border-color);border-radius:8px;background:var(--color-secondary);color:#292e29;font-weight:900;font-size:11px;cursor:pointer}.breakout-panel button:disabled{opacity:.5}.controls{display:flex;gap:7px;flex-wrap:wrap}.help-row{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 0;border-bottom:1px dashed var(--border-color);font-size:12px}.assignment,.child-room,.empty-room{padding:15px;border:2px solid var(--border-color);border-radius:11px;background:var(--bg-elevated)}.assignment{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px}.child-room{display:grid;gap:13px}.child-room h3{font-family:var(--font-display)}.current-roster{display:grid;gap:8px;padding:12px;border:1px dashed var(--border-color);border-radius:8px;background:var(--bg-surface);font-size:12px}.notice{padding:10px;border-left:3px solid var(--border-color);background:var(--bg-surface)}.breakout-panel button:focus-visible,.breakout-panel input:focus-visible,.breakout-panel select:focus-visible,.breakout-panel textarea:focus-visible{outline:3px dashed var(--color-accent-pink);outline-offset:2px}@media(max-width:780px){.breakout-workspace{grid-template-columns:1fr}.room-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.breakout-panel{padding:14px}.room-grid{grid-template-columns:1fr}.breakout-summary{flex-wrap:wrap}.refresh-link{margin-left:0}}
</style>
